from ..base import BaseInterface
from ...exception import BTSSMExecutionError


class BaseTRSCLIInterface(BaseInterface):
    READ_LOG_FILE_CMD = 'cat clt.log'

    def __init__(self):
        BaseInterface.__init__(self)
        self._error_indicator = "[ERROR]"

    def _check_for_errors(self, status_message):
        if self._error_indicator in status_message:
            errors = [line for line in status_message.splitlines() if self._error_indicator in line]
            error_message = '\n'.join([err[err.rfind(self._error_indicator) + len(self._error_indicator):].strip() for err in errors])
            error_message += "\nPlease refer to the Robot log files for details."
            raise BTSSMExecutionError(error_message)
